INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52411, 'Ezekiel 25:17', 'Ezekiel', 25, 17, 'زه به هغوی ته سخته سزا ورکړم او د هغوی نه به پوره بدل واخلم. هغوی ته به زما قهر معلوم شي. بیا به هغوی پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel25_verse_17.mp3', '', 1761754199, 1761754199),
(52412, 'Numbers 5:1', 'Numbers', 5, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_1.mp3', '', 1761754199, 1761754199),
(52413, 'Numbers 5:2', 'Numbers', 5, 2, '«د اسراییلو قوم ته امر وکړه چې هرڅوک چې د پوستکي په ساري ناروغۍ باندې اخته وي یا د بدن څخه یې زوه راوځي او هغه څوک چې په مړي باندې لګېدلی وي او ناپاک شوی وي د کمپ څخه وشړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_2.mp3', '', 1761754199, 1761754199),
(52414, 'Numbers 5:3', 'Numbers', 5, 3, 'دا ټول ناپاکه خلک که هغوی ښځې وي یا نارینه دباندې وباسئ، ترڅو هغه کمپ چې زه په کې د خپل قوم په منځ کې اوسېږم، ناپاکه نه کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_3.mp3', '', 1761754199, 1761754199),
(52415, 'Numbers 5:4', 'Numbers', 5, 4, 'اسراییلیانو همداسې وکړل. هغوی یې ټول د کمپ څخه وشړل. لکه څنګه چې څښتن موسی ته لارښوونه کړې وه، هغوی هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_4.mp3', '', 1761754199, 1761754199),
(52416, 'Numbers 5:5', 'Numbers', 5, 5, 'څښتن موسی ته وویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_5.mp3', '', 1761754199, 1761754199),
(52417, 'Numbers 5:6', 'Numbers', 5, 6, 'چې د اسراییلو قوم ته داسې ووایي: «که چېرې یو سړی یا یوه ښځه د یو چا په وړاندې جرم وکړي دا به زما په وړاندې ګناه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_6.mp3', '', 1761754199, 1761754199),
(52418, 'Numbers 5:7', 'Numbers', 5, 7, 'هغه باید د خپلې ګناه اقرار وکړي او هغه کس ته چې د هغه په وړاندې یې جرم کړی دی، پوره تاوان ورکړي او شل فیصده دې زیات هم ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_7.mp3', '', 1761754199, 1761754199),
(52419, 'Numbers 5:8', 'Numbers', 5, 8, 'خو که چېرې هغه کس مړ شوی وي او نژدې خپلوان چې تاوان ورته ورکول کېدای شي ونه لري، هغه به د کاهن په خاطر څښتن ته ورکړل شي. د دې بیې د ورکولو څخه برسېره باید یو پسه هم ورکړل شي چې د هغه کس د کفارې په ادا کولو کې ورڅخه کار واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_8.mp3', '', 1761754199, 1761754199),
(52420, 'Numbers 5:9', 'Numbers', 5, 9, 'ټولې سپېڅلې اعانې چې اسراییلیان یې کاهن ته راوړي، د هغه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_9.mp3', '', 1761754199, 1761754199),
(52421, 'Numbers 5:10', 'Numbers', 5, 10, 'هر کاهن دې هغه سپېڅلې نذرانې وساتي چې ورته ورکول کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_10.mp3', '', 1761754199, 1761754199),
(52422, 'Numbers 5:11', 'Numbers', 5, 11, 'څښتن موسی ته وویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_11.mp3', '', 1761754199, 1761754199),
(52423, 'Numbers 5:15', 'Numbers', 5, 15, 'په دواړو حالاتو کې به سړی خپله ښځه کاهن ته ورولي. هغه سړی دې د هغې په خاطر یو کیلو ګرام د اوربشو د اوړو نذرانه هم یوسي، خو په هغې باندې دې د زیتونو تېل یا قیمتي خوشبویي نه اچوي، ځکه چې دا نذرانه د یو شکمن مېړه له خوا د دې دپاره تیاریږي چې حقیقت معلوم شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_15.mp3', '', 1761754199, 1761754199),
(52424, 'Numbers 5:16', 'Numbers', 5, 16, 'کاهن به هغه ښځه راولي او د څښتن د قربانۍ د ځای مخې ته به یې ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_16.mp3', '', 1761754199, 1761754199),
(52425, 'Numbers 5:17', 'Numbers', 5, 17, 'هغه به لږې سپېڅلې اوبه د خټو په یوې کاسې کې واچوي او د سپېڅلې خېمې د غولي څخه به لږه خاوره واخلي او په اوبو کې به یې واچوي چې اوبه ترخې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_17.mp3', '', 1761754199, 1761754199),
(52426, 'Numbers 5:18', 'Numbers', 5, 18, 'بیا به هغه د ښځې ویښتان خپاره کړي او د اوړو نذرانه به د هغې په لاسونو کې کېږدي. کاهن به په خپلو لاسونو کې هغه کاسه ونیسي چې هغه ترخې اوبه په کې دي چې په ګناهکارانو باندې د څښتن لعنت راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_18.mp3', '', 1761754199, 1761754199),
(52427, 'Numbers 5:19', 'Numbers', 5, 19, 'بیا به کاهن په هغې ښځې باندې هغه قسم ومني چې هغه یې ورکوي او داسې به ووایي: «که چېرې تا زنا نه وي کړې، هغه لعنت به درته زیان ونه رسوي چې دغه اوبه یې راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_19.mp3', '', 1761754199, 1761754199),
(52428, 'Numbers 5:20', 'Numbers', 5, 20, 'خو که زنا دې کړې وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_20.mp3', '', 1761754199, 1761754199),
(52429, 'Numbers 5:21', 'Numbers', 5, 21, 'څښتن دې تا شنډه کړي او ستا ګېډه دې وپړسوي او په دې ډول دې ستا نوم په خپل قوم کې لعنتي کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_21.mp3', '', 1761754199, 1761754199),
(52430, 'Numbers 5:22', 'Numbers', 5, 22, 'دغه اوبه دې ستا په ګېډه کې ننوځي او هغه دې وپړسوي او تا دې شنډه کړي.» ښځه باید په ځواب کې داسې ووایي: «منم، څښتن دې همداسې وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_22.mp3', '', 1761754199, 1761754199),
(52431, 'Numbers 5:23', 'Numbers', 5, 23, 'بیا به کاهن دغه لعنت په یو کاغذ باندې ولیکي او هغه دې په ترخو اوبو کې ووینځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_23.mp3', '', 1761754199, 1761754199),
(52432, 'Numbers 5:24', 'Numbers', 5, 24, 'مخکې له دې چې په ښځې باندې هغه اوبه وڅښي چې په هغې باندې سخت درد راوستلی شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_24.mp3', '', 1761754199, 1761754199),
(52433, 'Numbers 5:25', 'Numbers', 5, 25, 'کاهن به د اوړو نذرانه د ښځې د لاسونو څخه واخلي او هغه دې څښتن ته د وقف کولو په خاطر پورته ونیسي او د قربانۍ ځای ته دې راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_25.mp3', '', 1761754199, 1761754199),
(52434, 'Numbers 5:26', 'Numbers', 5, 26, 'بیا به د هغې څخه یو موټی د نذرانې د یوې برخې په توګه واخلي او د قربانۍ په ځای باندې به یې وسوځوي. په اخر کې به په ښځې باندې هغه اوبه وڅښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_26.mp3', '', 1761754199, 1761754199),
(52435, 'Numbers 5:27', 'Numbers', 5, 27, 'که چېرې هغې زنا کړې وي، نو اوبه به سخت درد ورباندې راولي. د هغې ګېډه به وپړسیږي او هغه به شنډه شي او نوم به یې په خپل قوم کې لعنتي شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_27.mp3', '', 1761754199, 1761754199),
(52436, 'Numbers 5:28', 'Numbers', 5, 28, 'خو که چېرې هغه ښځه بې ګناه وي، نو زیان به ورته ونه رسیږي او اولادونه به وزېږولی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_28.mp3', '', 1761754199, 1761754199),
(52437, 'Numbers 5:31', 'Numbers', 5, 31, 'که چېرې مېړه په حقه نه وي نو سزا به ورته نه ورکول کیږي، خو که چېرې ښځه قصورواره وي، نو سزا به ورته ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers5_verse_31.mp3', '', 1761754199, 1761754199),
(52438, 'Genesis 49:1', 'Genesis', 49, 1, 'یعقوب خپل زامن راوغوښتل او ورته ویې ویل: «راټول شئ، ترڅو تاسو له هغه څه څخه خبر کړم چې په راتلونکې کې به په تاسو باندې پېښ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_1.mp3', '', 1761754199, 1761754199),
(52439, 'Genesis 49:2', 'Genesis', 49, 2, 'د یعقوب زامنو سره راټول شئ واورئ غوږ مو ونیسئ خپل پلار اسراییل ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_2.mp3', '', 1761754199, 1761754199),
(52440, 'Genesis 49:3', 'Genesis', 49, 3, 'ای روبینه! زما مشر زویه زما قوت یې ته زما د نارینتوب یې لومړنۍ نښه یې په عزت کې بهتر او په قدرت کې بهتر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_3.mp3', '', 1761754199, 1761754199),
(52441, 'Genesis 49:4', 'Genesis', 49, 4, 'یې بې‌کنتروله د سېلاب په شان نور به د ټولو نه بهتر نه یې په دې خاطر چې زما وینځې سره څملاستلې او تا کړ ناپاکه د خپل پلار کټ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_4.mp3', '', 1761754199, 1761754199),
(52442, 'Genesis 49:5', 'Genesis', 49, 5, 'دي شمعون او لاوي دواړه سره ورونه خپلو وسلو نه هغوی کار اخلي چې ظلم وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_5.mp3', '', 1761754199, 1761754199),
(52443, 'Genesis 49:6', 'Genesis', 49, 6, 'شریک به نه شمه د دوی پټو خبرو کې نه به د دوی په مجلسونو کې زه برخه واخلم په دې خاطر چې په خپل قهر کې یې خلک ووژل او په ملنډو یې غویان ګوډ کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_6.mp3', '', 1761754199, 1761754199),
(52444, 'Genesis 49:7', 'Genesis', 49, 7, 'لعنت دې وي د دوی په قهر باندې ځکه چې ډېر سخت ؤ او په غضب د هغوی چې ډېر ؤ بې‌رحمه د دوی نسل به په ټولو اسراییلو کې زه خپور کړم او زه به یې خپاره کړم د خپل قوم په منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_7.mp3', '', 1761754199, 1761754199),
(52445, 'Genesis 49:8', 'Genesis', 49, 8, 'ستا ستاینه به کوي ستا ورونه ای یهودا خپل دښمنان به له ورمېږه نیسې خپل سرونه به کړي ټیټ تاته ستا ورونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_8.mp3', '', 1761754199, 1761754199),
(52446, 'Genesis 49:9', 'Genesis', 49, 9, 'ای یهودا! ته د زمري بچی یې چې خپل ښکار ووژني او شي راستون خپل غار ته هغه د زمري په شان ټیټیږي او څملي هېڅوک نه شي کړای جرات هغه نا‌ارام کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_9.mp3', '', 1761754199, 1761754199),
(52447, 'Genesis 49:10', 'Genesis', 49, 10, 'یهودا سره به وي شاهي امسا تل به یې حکومت کړي اولاده ټول قومونه به راوړي هغه ته باج د ده په مخکې ټیټوي به هغوی د اطاعت سرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_10.mp3', '', 1761754199, 1761754199),
(52448, 'Genesis 49:11', 'Genesis', 49, 11, 'د انګور تاک پورې تړي به خپل خر په ډېر ښه شاخ پورې به کوټی تړي هغه کالي خپل په شرابو وینځي هغو شرابو کې چپنه وینځي چې دي د وینو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_11.mp3', '', 1761754199, 1761754199),
(52449, 'Genesis 49:12', 'Genesis', 49, 12, 'له شرابو څخه سرې دي د ده سترګې له شیدو څخه دي سپین د ده غاښونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_12.mp3', '', 1761754199, 1761754199),
(52450, 'Genesis 49:13', 'Genesis', 49, 13, 'زبولون به د دریاب په غاړه اوسي وي به بندر د کشتۍ‌ګانو تر صیدونه به یې سیمه ورسیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_13.mp3', '', 1761754199, 1761754199),
(52451, 'Genesis 49:14', 'Genesis', 49, 14, 'یساکار دی په مثال د قوي خر چې پرېوځي دی د دوه خورجینو منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_14.mp3', '', 1761754199, 1761754199),
(52452, 'Genesis 49:15', 'Genesis', 49, 15, 'دی چې وګوري چې ځای د اوسېدو یې ښه دی او ده خوشحالوونکې هغه خاوره دی به بار ته خپله ملا کاندي راټیټه د غلام په شان به کار ته شي مجبوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_15.mp3', '', 1761754199, 1761754199),
(52453, 'Genesis 49:16', 'Genesis', 49, 16, 'دان به کاندي په خپل قوم حکومت وي به د اسراییلو د نورو قبیلو په شان هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_16.mp3', '', 1761754199, 1761754199),
(52454, 'Genesis 49:17', 'Genesis', 49, 17, 'دان به وي د سرک د غاړې مار دی به په لاره کې وي منګری مار هغه به پوندې د اسونو چیچي ترڅو ولویږي سپور کس یې له شا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_17.mp3', '', 1761754199, 1761754199),
(52455, 'Genesis 49:18', 'Genesis', 49, 18, 'ستا د خلاصون په انتظار یمه زه ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_18.mp3', '', 1761754199, 1761754199),
(52456, 'Genesis 49:19', 'Genesis', 49, 19, 'په جاد به وشي یرغل د یرغلګرو له خوا دی به له شا نه په هغوی باندې یرغل وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_19.mp3', '', 1761754199, 1761754199),
(52457, 'Genesis 49:20', 'Genesis', 49, 20, 'د اشیر ځمکه به وي ښه حاصلخېزه ښه خوندور شاهي خواړه به یې تیار کړي له حاصله څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_20.mp3', '', 1761754199, 1761754199),
(52458, 'Genesis 49:21', 'Genesis', 49, 21, 'نفتالي هغه هوسۍ ده چې وهي ازادې منډې زېږوي ښکلي بچي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_21.mp3', '', 1761754199, 1761754199),
(52459, 'Genesis 49:22', 'Genesis', 49, 22, 'دی یوسف یو حاصلخېزه تاک یو مېوه‌داره ونه چې وي چینې په غاړه چې یې څانګې وي ختلې په دېوال باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_22.mp3', '', 1761754199, 1761754199),
(52460, 'Genesis 49:23', 'Genesis', 49, 23, 'کوي ده باندې سخته حمله خپل دښمنان د خپلو غشو او لیندو سره په ده پسې شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_23.mp3', '', 1761754199, 1761754199),
(52461, 'Genesis 49:24', 'Genesis', 49, 24, 'خو لینده د هغه پاتې شوه ثابته او شوې قوي د هغه مټې د یعقوب د قادر خدای په قدرت په وسیله د هغه شپونکي چې ساتندوی دی د اسراییلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_24.mp3', '', 1761754199, 1761754199),
(52462, 'Genesis 49:25', 'Genesis', 49, 25, 'دا دی خدای د ستا د پلار چې کړي کومک درسره مطلق قادر خدای دی چې برکت درکوي برکتونه د باران درکوي پاس له اسمانه څخه او د چینو له اوبو چې دي د ځمکې لاندې برکتونه به د ډېرو اولادونو او پادو درکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_25.mp3', '', 1761754199, 1761754199),
(52463, 'Genesis 49:26', 'Genesis', 49, 26, 'ستا پلار چې کوم برکتونه دي موندلي خپلو نیکونو څخه هغه ډېر لوی دي او لوی دي له هغو کوم چې راځي له ابدي غرونو برکتونه دې دا ټول وي د یوسف په سر د هغه چا په تندي چې شاهزاده دی د خپلو ورونو منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_26.mp3', '', 1761754199, 1761754199),
(52464, 'Genesis 49:27', 'Genesis', 49, 27, 'بنیامین دی په مثال د داړونکي لېوه په سهار کې دی خوري ښکار خپل په ماښام کې هغه وېشي غنیمت خپل»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_27.mp3', '', 1761754199, 1761754199),
(52465, 'Genesis 49:28', 'Genesis', 49, 28, 'دا ټولې د اسراییلو دولس قبیلې دي او دا هغه څه وو چې د هغوی پلار دوی ته د برکت ورکولو په وخت کې وویل او هر یو ته یې هغه برکت ورکړ چې ورسره مناسب ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_28.mp3', '', 1761754199, 1761754199),
(52466, 'Genesis 49:29', 'Genesis', 49, 29, 'بیا یعقوب هغوی ته دغه وصیت وکړ: «زه به زر مړ شم او د خپلو نیکونو سره به یوځای شم. ما د خپلو نیکونو سره په هغې سمڅې کې ښخ کړئ چې د حیتي عفرون په پټي کې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_29.mp3', '', 1761754199, 1761754199),
(52467, 'Genesis 49:30', 'Genesis', 49, 30, 'دا هغه سمڅه ده چې د مکفیلې په پټي کې ممري ته مخامخ د کنعان په خاوره کې پرته ده او ابراهیم هغه د پټي سره د عفرون څخه د هدیرې دپاره اخیستې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_30.mp3', '', 1761754199, 1761754199),
(52468, 'Genesis 49:31', 'Genesis', 49, 31, 'دا هغه ځای دی چې ابراهیم او د هغه ښځه ساره او اسحاق او د هغه ښځه ربکا په کې ښخ شوي وو او هلته مې لیه هم ښخه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_31.mp3', '', 1761754199, 1761754199),
(52469, 'Genesis 49:32', 'Genesis', 49, 32, 'هغه پټی او سمڅه د حیتیانو څخه اخیستل شوي وو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_32.mp3', '', 1761754199, 1761754199),
(52470, 'Genesis 49:33', 'Genesis', 49, 33, 'کله چې یعقوب خپلو زامنو ته دا وصیت وکړ، هغه بېرته څملاست او مړ شو او د خپلو نیکونو سره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis49_verse_33.mp3', '', 1761754199, 1761754199),
(52471, 'Zechariah 12:1', 'Zechariah', 12, 1, 'د بنى اِسرائيلو په حقله دا د مالِک خُدائ پېغام دے. د هغه مالِک خُدائ، چا چې آسمانونه خوارۀ کړى دى، چا چې د زمکې بنيادونه اېښى دى، او چا چې بنى آدم له ساه ورکړې ده، هغه فرمائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_1.mp3', '', 1761754199, 1761754199),
(52472, 'Zechariah 12:2', 'Zechariah', 12, 2, '”زۀ به يروشلم نه د شرابو پياله جوړه کړم چې ګېرچاپېره قومونه يې په څښلو سره سرګردانه شى، کله چې هغوئ خپل فوجيان د يهوداه او يروشلم محاصره کولو دپاره رالېږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_2.mp3', '', 1761754199, 1761754199),
(52473, 'Zechariah 12:3', 'Zechariah', 12, 3, 'په هغه ورځ، کله چې د زمکې ټول قومونه د دې خلاف يو ځائ شى، زۀ به د يروشلم نه د ټولو قومونو دپاره يو نۀ خوځېدونکے کاڼے جوړ کړم. هر هغه څوک چې د دې د لرې کولو کوشش کوى هغوئ به خپل ځانونه زخمى کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_3.mp3', '', 1761754199, 1761754199),
(52474, 'Zechariah 12:4', 'Zechariah', 12, 4, 'په هغه ورځ به زۀ هر آس اوتر کړم او د دې سوارۀ به ليونى کړم،“ مالِک خُدائ فرمائى. ”زۀ به د يهوداه په قوم باندې نظر ساتم. خو زۀ به د دوئ د دشمنانو ټول آسونه ړاندۀ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_4.mp3', '', 1761754199, 1761754199),
(52475, 'Zechariah 12:5', 'Zechariah', 12, 5, 'بيا د يهوداه حکمرانان به په خپلو زړونو کښې وائى، د يروشلم خلق مضبوط دى، ځکه چې مالِک خُدائ ربُ الافواج د هغوئ خُدائ پاک دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_5.mp3', '', 1761754199, 1761754199),
(52476, 'Zechariah 12:6', 'Zechariah', 12, 6, 'په هغه ورځ به زۀ د يهوداه حکمرانان لکه د لرګو اور، لکه لمبه وهونکى مشعل چې د غنمو د ګېډۍ په مينځ کښې وى جوړ کړم. دا به ښى او ګس طرف ته ګېرچاپېره ټول خلق وسوزوى، خو يروشلم به په خپل ځائ روغ رمټ پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_6.mp3', '', 1761754199, 1761754199),
(52477, 'Zechariah 12:7', 'Zechariah', 12, 7, 'مالِک خُدائ به د يروشلم نه وړاندې نورو يهوديانو ته کاميابې ورکړى، تر دې چې د يروشلم خلقو او د داؤد شاهى خاندان ته د يهوداه نه زيات عزت مِلاو نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_7.mp3', '', 1761754199, 1761754199),
(52478, 'Zechariah 12:8', 'Zechariah', 12, 8, 'په هغه ورځ به مالِک خُدائ هغه خلق بچ کړى څوک چې په يروشلم کښې اوسيږى، نو په هغوئ کښې به د ټولو نه کمزورى د داؤد هومره طاقتور وى، او د داؤد اولاد به داسې وى لکه چې خُدائ پاک او لکه چې د مالِک خُدائ يوه فرښته په خپله د هغوئ نه وړاندې روانه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_8.mp3', '', 1761754199, 1761754199),
(52479, 'Zechariah 12:9', 'Zechariah', 12, 9, 'په هغه ورځ به زۀ د هغه ټولو قومونو تباه کول شروع کړم کوم چې په يروشلم حمله کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_9.mp3', '', 1761754199, 1761754199),
(52480, 'Zechariah 12:10', 'Zechariah', 12, 10, 'زۀ به د داؤد په اولاد او څوک چې په يروشلم کښې اوسيږى د فضل او دُعا روح نازل کړم. هغوئ به ما ته ګورى، هغه چا ته چې دوئ په نېزه وهلے دے، او هغوئ به د هغۀ دپاره داسې ماتم وکړى لکه چې څوک په خپل ايکې يو ماشوم ماتم کوى، او ډېر سخت به خفه شى لکه د چا چې اولنے زوئ مړ شوے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_10.mp3', '', 1761754199, 1761754199),
(52481, 'Zechariah 12:11', 'Zechariah', 12, 11, 'په هغه ورځ به په يروشلم کښې لوئ وير وى، داسې لکه د هددرمون وير چې د مِجدو په مېدان کښې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_11.mp3', '', 1761754199, 1761754199),
(52482, 'Zechariah 12:12', 'Zechariah', 12, 12, 'ټول مُلک به ماتم کوى، هره يوه قبيله به په خپله د خپلو ښځو نه جُدا يعنې، د داؤد د خاندان قبيله به خپلو ښځو نه جُدا، د ناتن قبيله به خپلو ښځو نه جُدا،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_12.mp3', '', 1761754199, 1761754199),
(52483, 'Zechariah 12:13', 'Zechariah', 12, 13, 'د ليوى قبيلې به د خپلو ښځو نه جُدا، د سِمعى قبيله به خپلو ښځو نه جُدا،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_13.mp3', '', 1761754199, 1761754199),
(52484, 'Zechariah 12:14', 'Zechariah', 12, 14, 'او هره پاتې شوې قبيله به ځان ځان له ماتم کوى او د دوئ ښځې به هم ځانله ماتم کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah12_verse_14.mp3', '', 1761754199, 1761754199),
(52485, 'Ezekiel 12:1', 'Ezekiel', 12, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_1.mp3', '', 1761754199, 1761754199),
(52486, 'Ezekiel 12:2', 'Ezekiel', 12, 2, '«ای فاني انسانه، ته د سرکښه قوم په منځ کې اوسېږې. هغوی سترګې لري، خو هېڅ شی نه ویني او هغوی غوږونه لري خو هېڅ هم نه اوري، ځکه چې هغوی سرکښه قوم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_2.mp3', '', 1761754199, 1761754199),
(52487, 'Ezekiel 12:3', 'Ezekiel', 12, 3, 'نو اوس ای فاني انسانه، لکه د یو جلاوطن په شان خپل د سفر سامان تیار کړه او د ورځې له خوا حرکت وکړه. پرېږده چې ټول دې ووینې چې ته روان شوې او بل ځای ته لاړې. کېدای شي چې دغه سرکښه قوم ستا دې کار ته پام وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_3.mp3', '', 1761754199, 1761754199),
(52488, 'Ezekiel 12:4', 'Ezekiel', 12, 4, 'په رڼا ورځ دې خپل د جلاوطنۍ سامان دباندې وباسه، ترڅو هغوی تا وویني. بیا ته په ماښام کې د هغه چا په شان چې جلاوطنۍ ته روان وي، حرکت وکړه او پرېږده چې هغوی تا وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_4.mp3', '', 1761754199, 1761754199),
(52489, 'Ezekiel 12:5', 'Ezekiel', 12, 5, 'د هغوی په مخکې د خپل کور دېوال سوری کړه او خپل د جلاوطنۍ سامان دې د هغې لارې نه وباسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_5.mp3', '', 1761754199, 1761754199),
(52490, 'Ezekiel 12:6', 'Ezekiel', 12, 6, 'خپل پنډ دې د هغوی په مخکې په خپلو اوږو باندې کېږده او په تیاره کې یې دباندې یوسه. خپل مخ پټ کړه، ترڅو هغه ځمکه ونه وینې چې ته یې پرېږدې. ستا دا کار به د اسراییلیانو دپاره د خبردارۍ یوه نښه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_6.mp3', '', 1761754199, 1761754199),
(52491, 'Ezekiel 12:7', 'Ezekiel', 12, 7, 'لکه څنګه چې څښتن راته ویلي وو ما هماغسې وکړل. ما د یو جلاوطني په شان خپل د سفر سامان د ورځې له خوا دباندې وویست. بیا د ماښام په تیاره کې مې په خپلو لاسونو باندې دېوال سوری کړ او د سفر د سامان سره ووتلم. هغوی ټولو کتل چې ما خپل پنډ په اوږو کړ او په تیاره کې لاړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_7.mp3', '', 1761754199, 1761754199),
(52492, 'Ezekiel 12:8', 'Ezekiel', 12, 8, 'سبا سهار څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_8.mp3', '', 1761754199, 1761754199),
(52493, 'Ezekiel 12:9', 'Ezekiel', 12, 9, '«ای فاني انسانه، ایا د اسراییلو سرکښه قوم ستا څخه پوښتنه ونه کړه چې ته څه کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_9.mp3', '', 1761754199, 1761754199),
(52494, 'Ezekiel 12:10', 'Ezekiel', 12, 10, 'هغوی ته ووایه چې زه څښتن تعالی هغوی ته داسې وایم. دا پیغام د اورشلیم د پاچا او د هغو ټولو اسراییلیانو په اړه دی چې هلته اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_10.mp3', '', 1761754199, 1761754199),
(52495, 'Ezekiel 12:11', 'Ezekiel', 12, 11, 'هغوی ته ووایه چې تا چې څه کړي دي، دا هغه نښه ده چې د هغوی سره به هم همداسې کیږي. هغوی به مهاجر شي او اسیران به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_11.mp3', '', 1761754199, 1761754199),
(52496, 'Ezekiel 12:12', 'Ezekiel', 12, 12, 'کوم پاچا چې په هغوی باندې حکومت کوي، هغه به هم خپل پنډ په تیاره کې په خپلو اوږو باندې کېږدي او د دېوال د هغه سوري له لارې به وتښتي چې هغوی یې د هغه دپاره وباسي. هغه به خپل مخ پټ کړي، ترڅو هغه ځمکه ونه ویني چې پرېږدي یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_12.mp3', '', 1761754199, 1761754199),
(52497, 'Ezekiel 12:13', 'Ezekiel', 12, 13, 'خو زه څښتن به په هغه باندې خپل جال خپور کړم او په کې راګېر به یې کړم. بیا به زه هغه د بابل هېواد ته بوځم، خو هغه به دا هېواد ونه ویني او هلته به مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_13.mp3', '', 1761754199, 1761754199),
(52498, 'Ezekiel 12:14', 'Ezekiel', 12, 14, 'زه به د هغه د دربار ټول خلک، د هغه مشاوران او لښکرې هرې خواته خورې ورې کړم او زه به هغوی په خپلې تورې سره تعقیب کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_14.mp3', '', 1761754199, 1761754199),
(52499, 'Ezekiel 12:15', 'Ezekiel', 12, 15, 'کله چې مې هغوی په نورو قومونو او وطنونو کې خواره واره کړل، نو بیا به پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_15.mp3', '', 1761754199, 1761754199),
(52500, 'Ezekiel 12:16', 'Ezekiel', 12, 16, 'خو زه به د هغوی نه لږ خلک د جنګ، قحطۍ او وبا نه ژوندي پرېږدم، نو هغوی چې کومو هېوادنو ته ځي، په خپلو ناوړو او د کرکې وړ عملونو باندې به اقرار وکړي. بیا به په دې پوه شي چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_16.mp3', '', 1761754199, 1761754199),
